-- PER 설명 보강: 주가·주당순이익을 먼저 풀어 준다 (new_words.py와 같은 내용)
UPDATE public.words SET meaning = '주식 1주 가격이 그 주식이 1년에 버는 돈의 몇 배인지 보여주는 숫자',
  visuals = '[{"type": "text", "title": "먼저 두 단어부터", "body": "주가: 주식 1주의 가격이에요.\n주당순이익(EPS): 회사가 1년 동안 번 돈(순이익)을 주식 수로 나눈 값이에요. 주식 1주가 1년에 번 돈이라고 보면 돼요."}, {"type": "text", "title": "PER은 이렇게 계산해요", "body": "PER = 주가 ÷ 주당순이익\n\n회사가 1년에 1억 원을 벌고 주식이 1만 주라면, 1주가 번 돈은 1만 원이에요.\n주가가 10만 원이면 PER은 10만 ÷ 1만 = 10배예요.\n지금 가격이면 이 회사가 10년 동안 번 돈으로 본전을 찾는다는 뜻이에요."}, {"type": "table", "title": "PER이 높을 때와 낮을 때", "columns": ["PER", "뜻", "주의할 점"], "rows": [["높다 (예: 30배)", "버는 돈에 비해 비싸게 거래돼요", "앞으로 크게 성장할 거라는 기대가 담겼을 수도 있어요"], ["낮다 (예: 5배)", "버는 돈에 비해 싸게 거래돼요", "성장 기대가 작거나 곧 이익이 줄 거라 보는 것일 수도 있어요"]], "caption": "같은 업종끼리 비교해야 의미가 있어요. 반도체와 은행의 PER을 그대로 비교하면 안 돼요."}, {"type": "flow", "title": "금리가 오르면 적정 PER이 낮아지는 이유", "steps": ["금리 ↑", "예금·채권으로도 안전하게 더 벌 수 있음", "주식에 기대하는 수익률 ↑", "같은 이익에 매기는 값 ↓", "적정 PER ↓ (주가 부담)"], "caption": "금리가 내리면 반대로 같은 이익에도 더 높은 값을 쳐줘 PER이 높아지기 쉬워요."}]'::jsonb
WHERE id = 755;

SELECT id, word, meaning, jsonb_array_length(visuals) AS n FROM public.words WHERE id = 755;
